package vn.gasstation.integration.seenpro.parser;
import java.util.*;import org.jsoup.Jsoup;import org.jsoup.nodes.Element;import org.slf4j.*;import org.springframework.stereotype.Component;import vn.gasstation.integration.seenpro.model.SeenProCustomerRow;
@Component public class SeenProCustomerHtmlParser {private static final Logger log=LoggerFactory.getLogger(SeenProCustomerHtmlParser.class);
 public List<SeenProCustomerRow> parse(String html){var document=Jsoup.parse(html==null?"":html);var rows=document.select(".chiTiet > .rowx.setrow");log.info("[SEENPRO] event=parser.document parser=customer title={} rowCount={}",document.title(),rows.size());if(rows.isEmpty()){log.warn("[SEENPRO] event=parser.failed parser=customer failureStage=NO_CUSTOMER_ROWS");return List.of();}var result=new ArrayList<SeenProCustomerRow>();int skipped=0;for(Element row:rows){var secondary=childrenWithClass(row,"dienThoai");String code=text(secondary,1),name=text(childWithClass(row,"tenKhachHang"));if(code==null||name==null){skipped++;continue;}result.add(new SeenProCustomerRow(code,name,text(secondary,0),text(childWithClass(row,"diaChix")),text(childWithClass(row,"nguoiDaiDien"))));}log.info("[SEENPRO] event=parser.completed parser=customer count={} skipped={}",result.size(),skipped);return List.copyOf(result);}
 private List<Element> childrenWithClass(Element parent,String className){return parent.children().stream().filter(child->child.hasClass(className)).toList();}
 private Element childWithClass(Element parent,String className){return parent.children().stream().filter(child->child.hasClass(className)).findFirst().orElse(null);}
 private String text(List<Element> elements,int index){return index<elements.size()?text(elements.get(index)):null;}private String text(Element element){if(element==null)return null;String value=element.text().trim().replaceAll("\\s+"," ");return value.isBlank()?null:value;}}
